//! Wire Protocol v2 control-plane schema — a Rust transcription of
//! `protos/wire-protocol-v2/control.proto`.
//!
//! The proto file is the normative schema (spec §4, accepted 2026-11-12);
//! these types are written by hand instead of generated by `protoc`, so the
//! workspace builds with plain `cargo` and no protobuf toolchain — the same
//! approach as the v1 `AudioFormat` types in `audio-share-core`. Every field
//! number, type, and enum value below mirrors the frozen proto file exactly;
//! this module adds no fields and renumbers nothing.
//!
//! The fixture replay contract (the golden-vector replayer) reads
//! `fixtures/wire-protocol-v2/` and round-trips these types byte-for-byte; the
//! implementation has no private encoding (spec §11.1).

/// Envelope for every control-stream message (spec §4.1; proto `Frame`).
///
/// The oneof case is the message type — behavior never depends on enum
/// ordinals, struct layout, or the position of a four-byte command. A `Frame`
/// with no `body` set is malformed (401).
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Frame {
    #[prost(
        oneof = "frame::Body",
        tags = "1, 2, 3, 4, 5, 6, 7, 8, 16, 17, 18, 19, 32, 33, 34, 35, 36, 37, 48, 49, 64"
    )]
    pub body: Option<frame::Body>,
}

/// Nested message and enum types in scope for the `Frame` envelope.
pub mod frame {
    /// Band assignments follow spec §4.1 (proto `Frame.body`):
    /// connection 1–8 · pairing 16–19 · subscription/config 32–37 ·
    /// stream lifecycle 48–49 · diagnostics 64. Everything else is reserved.
    #[derive(Clone, PartialEq, ::prost::Oneof)]
    pub enum Body {
        /// Band 1–15: connection lifecycle.
        #[prost(message, tag = "1")]
        AuthInit(super::AuthInit),
        #[prost(message, tag = "2")]
        AuthChallenge(super::AuthChallenge),
        #[prost(message, tag = "3")]
        AuthProof(super::AuthProof),
        #[prost(message, tag = "4")]
        AuthResult(super::AuthResult),
        #[prost(message, tag = "5")]
        Error(super::Error),
        #[prost(message, tag = "6")]
        Close(super::Close),
        #[prost(message, tag = "7")]
        Negotiate(super::Negotiate),
        #[prost(message, tag = "8")]
        NegotiateResponse(super::NegotiateResponse),
        /// Band 16–31: pairing.
        #[prost(message, tag = "16")]
        PairingRequest(super::PairingRequest),
        #[prost(message, tag = "17")]
        PairingResponse(super::PairingResponse),
        #[prost(message, tag = "18")]
        PairingConfirm(super::PairingConfirm),
        #[prost(message, tag = "19")]
        PairingResult(super::PairingResult),
        /// Band 32–47: subscription and configuration publication.
        #[prost(message, tag = "32")]
        Subscribe(super::Subscribe),
        #[prost(message, tag = "33")]
        SubscribeResponse(super::SubscribeResponse),
        #[prost(message, tag = "34")]
        Unsubscribe(super::Unsubscribe),
        #[prost(message, tag = "35")]
        UnsubscribeResponse(super::UnsubscribeResponse),
        #[prost(message, tag = "36")]
        RequestConfiguration(super::RequestConfiguration),
        #[prost(message, tag = "37")]
        ConfigurationPublished(super::ConfigurationPublished),
        /// Band 48–63: stream-instance lifecycle.
        #[prost(message, tag = "48")]
        StreamStarted(super::StreamStarted),
        #[prost(message, tag = "49")]
        StreamEnded(super::StreamEnded),
        /// Band 64–79: diagnostics (spec §9).
        #[prost(message, tag = "64")]
        PlaybackDiagnostics(super::PlaybackDiagnostics),
    }
}

/// Per-message status (spec §4.2; proto `Status`). Field 2 of every response.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Status {
    /// 0 = success; otherwise a §6 registry code.
    #[prost(uint32, tag = "1")]
    pub code: u32,
    /// Meaningful when `code != 0`; MUST equal the §6.2 registry default in v2.0.
    #[prost(bool, tag = "2")]
    pub retryable: bool,
    /// Meaningful when `code != 0`; MUST equal the §6.2 registry default in v2.0.
    #[prost(bool, tag = "3")]
    pub requires_repairing: bool,
    /// ≤ 256 bytes UTF-8; no secrets, paths, or stack traces; pre-auth
    /// responses carry none (§4.2).
    #[prost(string, tag = "4")]
    pub detail: String,
}

impl Status {
    /// A success status: all fields at their proto3 defaults, encoded present.
    pub const fn ok() -> Self {
        Self {
            code: 0,
            retryable: false,
            requires_repairing: false,
            detail: String::new(),
        }
    }

    /// Build a status from a §6 registry code, carrying the registry's
    /// `retryable` and `requires_repairing` defaults (spec §4.2, §6.2).
    pub fn registry(code: u32) -> Self {
        let (retryable, requires_repairing) = registry_defaults(code);
        Self {
            code,
            retryable,
            requires_repairing,
            detail: String::new(),
        }
    }

    /// Attach a bounded detail (≤ 256 bytes; callers pre-check the §10 bound).
    pub fn with_detail(mut self, detail: impl Into<String>) -> Self {
        self.detail = detail.into();
        self
    }
}

/// The §6.2 registry defaults for `retryable` and `requires_repairing`
/// (`true`, `true` columns in the table order: retryable, re-pairing).
///
/// Single source of truth: the code table lives in [`crate::codes::ErrorCode`];
/// adding or changing a code must not touch a second copy here.
pub(crate) fn registry_defaults(code: u32) -> (bool, bool) {
    crate::codes::ErrorCode::from_code(code)
        .map(|entry| (entry.retryable, entry.requires_repairing))
        .unwrap_or((false, false))
}

// ---------------------------------------------------------------------------
// Connection lifecycle (band 1–15; spec §4.4). Authorization is a signed
// challenge against the Client identity key, never a bearer token (pairing.md
// §9.1, PR-9).
// ---------------------------------------------------------------------------

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct AuthInit {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    /// ECDSA P-256, SEC1 compressed, 33 bytes (pairing.md §2, §9.1).
    #[prost(bytes = "vec", tag = "2")]
    pub client_public_key: Vec<u8>,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct AuthChallenge {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    /// 32 bytes, CSPRNG (pairing.md §9.1).
    #[prost(bytes = "vec", tag = "2")]
    pub server_random: Vec<u8>,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct AuthProof {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    /// ECDSA-P256-SHA256 r||s, fixed 64 bytes (IEEE P1363), over the RAW
    /// auth_context bytes — exactly one hash (pairing.md §9.1).
    #[prost(bytes = "vec", tag = "2")]
    pub signature: Vec<u8>,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct AuthResult {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    #[prost(message, required, tag = "2")]
    pub status: Status,
    /// Server-assigned (counter from 1); set iff success (spec §4.4).
    #[prost(fixed64, tag = "3")]
    pub session_id: u64,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Negotiate {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    /// MUST be 2 (spec §4.4).
    #[prost(uint32, tag = "2")]
    pub protocol_major: u32,
    /// 0 for v2.0.
    #[prost(uint32, tag = "3")]
    pub protocol_minor: u32,
    /// Optional-feature ids, ascending, unique (spec §4.5).
    #[prost(uint32, repeated, packed = "true", tag = "4")]
    pub capabilities: Vec<u32>,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct NegotiateResponse {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    #[prost(message, required, tag = "2")]
    pub status: Status,
    /// Accepted major.
    #[prost(uint32, tag = "3")]
    pub protocol_major: u32,
    /// Server's minor within major 2.
    #[prost(uint32, tag = "4")]
    pub protocol_minor: u32,
    /// Intersection honored for this session (spec §4.5).
    #[prost(uint32, repeated, packed = "true", tag = "5")]
    pub capabilities: Vec<u32>,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Error {
    /// Echo of the failed request; 0 = unsolicited.
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    /// `status.code` MUST be != 0 (spec §4.4 validation table).
    #[prost(message, required, tag = "2")]
    pub status: Status,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Close {
    /// §6 registry code; MUST be != 0.
    #[prost(uint32, tag = "1")]
    pub code: u32,
    /// ≤ 256 bytes UTF-8 (spec §4.4).
    #[prost(string, tag = "2")]
    pub detail: String,
}

// ---------------------------------------------------------------------------
// Pairing (band 16–31; spec §4.4, pairing.md §6.2). Wire slots only — the
// sequence and crypto semantics are the pairing specification's (ticket 04).
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum PairingMode {
    Unspecified = 0,
    /// QR payload presented; `pairing_nonce` required (spec §4.4).
    Qr = 1,
    /// No camera; SAS comparison on both screens (spec §4.4).
    Sas = 2,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct PairingRequest {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    #[prost(enumeration = "PairingMode", tag = "2")]
    pub pairing_mode: i32,
    /// 16 bytes; QR mode only (pairing.md §4–§5).
    #[prost(bytes = "vec", tag = "3")]
    pub pairing_nonce: Vec<u8>,
    /// 32 bytes, CSPRNG.
    #[prost(bytes = "vec", tag = "4")]
    pub client_random: Vec<u8>,
    /// ECDSA P-256, SEC1 compressed, 33 bytes.
    #[prost(bytes = "vec", tag = "5")]
    pub client_public_key: Vec<u8>,
    /// MUST equal the ALPN major (2).
    #[prost(uint32, tag = "6")]
    pub protocol_major: u32,
    /// Client's offered set; input to the binding (pairing.md §6.3).
    #[prost(uint32, repeated, packed = "true", tag = "7")]
    pub capabilities: Vec<u32>,
    /// ≤ 63 bytes UTF-8 display name.
    #[prost(string, tag = "8")]
    pub client_name: String,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct PairingResponse {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    #[prost(message, required, tag = "2")]
    pub status: Status,
    /// Echo.
    #[prost(enumeration = "PairingMode", tag = "3")]
    pub pairing_mode: i32,
    /// Echo, QR mode only.
    #[prost(bytes = "vec", tag = "4")]
    pub pairing_nonce: Vec<u8>,
    /// Echo.
    #[prost(bytes = "vec", tag = "5")]
    pub client_random: Vec<u8>,
    /// 32 bytes, CSPRNG.
    #[prost(bytes = "vec", tag = "6")]
    pub server_random: Vec<u8>,
    /// 32 bytes raw Ed25519 identity public key.
    #[prost(bytes = "vec", tag = "7")]
    pub server_public_key: Vec<u8>,
    /// Echo.
    #[prost(uint32, tag = "8")]
    pub protocol_major: u32,
    /// Echo of the offered set.
    #[prost(uint32, repeated, packed = "true", tag = "9")]
    pub capabilities: Vec<u32>,
    /// 48 bytes, TLS-Exporter bound to the transcript (pairing.md §6.3).
    #[prost(bytes = "vec", tag = "10")]
    pub binding: Vec<u8>,
    /// 8 raw bytes = first 8 of SHA-256(client_public_key) (pairing.md §8.1).
    #[prost(bytes = "vec", tag = "11")]
    pub client_id: Vec<u8>,
    /// Accepted display name, ≤ 63 bytes UTF-8.
    #[prost(string, tag = "12")]
    pub display_name: String,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct PairingConfirm {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    /// 48 bytes; the Client's own exporter derivation (pairing.md §6.3).
    #[prost(bytes = "vec", tag = "2")]
    pub binding_echo: Vec<u8>,
    /// 64 bytes; one ECDSA-P256-SHA256 r||s signature by the claimed identity
    /// key over the pairing proof input (pairing.md §6.3.1); the Server
    /// verifies BEFORE persisting the identity or PairingResult(OK).
    #[prost(bytes = "vec", tag = "3")]
    pub client_proof: Vec<u8>,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct PairingResult {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    /// OK: pairing persisted; else a §6 code.
    #[prost(message, required, tag = "2")]
    pub status: Status,
}

// ---------------------------------------------------------------------------
// Subscription and configuration (band 32–47; spec §4.4).
// ---------------------------------------------------------------------------

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Subscribe {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct SubscribeResponse {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    #[prost(message, required, tag = "2")]
    pub status: Status,
    /// Set iff success (spec §4.4).
    #[prost(message, tag = "3")]
    pub configuration: Option<Configuration>,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Unsubscribe {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct UnsubscribeResponse {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    #[prost(message, required, tag = "2")]
    pub status: Status,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct RequestConfiguration {
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct ConfigurationPublished {
    /// 0 = unsolicited push; > 0 = response to `RequestConfiguration`.
    #[prost(fixed64, tag = "1")]
    pub request_id: u64,
    #[prost(message, tag = "2")]
    pub configuration: Option<Configuration>,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Configuration {
    /// ∈ [1, 2^32−1]; +1 per decode-affecting change within an instance.
    #[prost(uint32, tag = "1")]
    pub config_generation: u32,
    /// CODEC_PCM in v2.0.
    #[prost(enumeration = "Codec", tag = "2")]
    pub codec: i32,
    /// Set iff `codec == CODEC_PCM`.
    #[prost(message, tag = "3")]
    pub pcm: Option<PcmParameters>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum Codec {
    Unspecified = 0,
    /// Required first codec (spec §4.4).
    Pcm = 1,
}

/// SampleFormat numbers mirror v1 `AudioFormat.Encoding` (docs/protocol.md §3).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum SampleFormat {
    Unspecified = 0,
    /// IEEE-754 binary32 little-endian.
    F32Le = 1,
    U8 = 2,
    S16Le = 3,
    /// Packed 3-byte little-endian.
    S24Le = 4,
    S32Le = 5,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct PcmParameters {
    /// Hz, > 0.
    #[prost(uint32, tag = "1")]
    pub sample_rate: u32,
    /// > 0.
    #[prost(uint32, tag = "2")]
    pub channels: u32,
    /// MUST NOT be UNSPECIFIED (spec §4.4 validation table).
    #[prost(enumeration = "SampleFormat", tag = "3")]
    pub sample_format: i32,
}

// ---------------------------------------------------------------------------
// Stream-instance lifecycle (band 48–63; spec §4.4). Only the Server pushes
// these messages (spec §5.4 invariant 3).
// ---------------------------------------------------------------------------

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct StreamStarted {
    #[prost(uint32, tag = "1")]
    pub stream_instance_id: u32,
    /// Generation of the media that follows.
    #[prost(uint32, tag = "2")]
    pub config_generation: u32,
    /// Capture-clock position of the first media frame the receiver will get
    /// (0 for a fresh instance; mid-stream anchor for a late Subscriber).
    #[prost(fixed64, tag = "3")]
    pub initial_timestamp: u64,
}

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct StreamEnded {
    #[prost(uint32, tag = "1")]
    pub stream_instance_id: u32,
    /// §6: 501 CAPTURE_FAILURE, 502 STREAM_ENDED, 503 SERVER_STOPPING, …
    #[prost(uint32, tag = "2")]
    pub code: u32,
    #[prost(string, tag = "3")]
    pub detail: String,
}

// ---------------------------------------------------------------------------
// Diagnostics (band 64–79; spec §9). Client → Server push, every 5 s and
// best-effort once when entering CLOSING; at most one send may be pending.
// ---------------------------------------------------------------------------

#[derive(Clone, PartialEq, ::prost::Message)]
pub struct PlaybackDiagnostics {
    #[prost(uint32, tag = "1")]
    pub stream_instance_id: u32,
    #[prost(uint32, tag = "2")]
    pub config_generation: u32,
    /// RFC 3550 A.1 cycles folded in.
    #[prost(fixed64, tag = "3")]
    pub extended_highest_sequence: u64,
    /// RFC 3550 A.3; signed — duplicates may drive it negative.
    #[prost(sint64, tag = "4")]
    pub cumulative_lost: i64,
    #[prost(sint64, tag = "5")]
    pub interval_lost: i64,
    #[prost(fixed64, tag = "6")]
    pub cumulative_received: u64,
    #[prost(fixed64, tag = "7")]
    pub interval_received: u64,
    #[prost(fixed64, tag = "8")]
    pub cumulative_duplicates: u64,
    #[prost(fixed64, tag = "9")]
    pub interval_duplicates: u64,
    /// Out-of-order arrivals.
    #[prost(fixed64, tag = "10")]
    pub cumulative_reordered: u64,
    #[prost(fixed64, tag = "11")]
    pub interval_reordered: u64,
    /// Max observed sequence displacement, this instance.
    #[prost(uint32, tag = "12")]
    pub max_reorder_distance: u32,
    #[prost(fixed64, tag = "13")]
    pub cumulative_late_drops: u64,
    #[prost(fixed64, tag = "14")]
    pub interval_late_drops: u64,
    /// Unknown or superseded generation (§7.5/§7.6).
    #[prost(fixed64, tag = "15")]
    pub cumulative_unknown_config_drops: u64,
    #[prost(fixed64, tag = "16")]
    pub interval_unknown_config_drops: u64,
    /// Interventions: gap, underrun, drift, re-anchor.
    #[prost(fixed64, tag = "17")]
    pub cumulative_concealments: u64,
    #[prost(fixed64, tag = "18")]
    pub interval_concealments: u64,
    /// Frames inserted − frames deleted, this instance.
    #[prost(sint64, tag = "19")]
    pub concealed_frames: i64,
    #[prost(fixed64, tag = "20")]
    pub underruns: u64,
    /// RFC 3550 A.8 estimate, converted at the published sample_rate.
    #[prost(uint32, tag = "21")]
    pub jitter_microseconds: u32,
    #[prost(uint32, tag = "22")]
    pub buffer_current_ms: u32,
    #[prost(uint32, tag = "23")]
    pub buffer_target_ms: u32,
    /// Most recent frame position handed to the platform playback API, on the
    /// capture clock of the active instance.
    #[prost(fixed64, tag = "24")]
    pub submitted_position: u64,
}
